/* Each route owns a different interaction. Abort listeners before replacing its DOM. */
Night.pages = (() => {
  let scope, savedHandler = () => {}; const animations = new Set();
  const esc = Night.escape;
  function dispose() { Night.gallery.unmount();scope?.abort(); animations.forEach(a=>a?.cancel()); animations.clear(); savedHandler=()=>{}; }
  function mount(page) {
    dispose(); scope = new AbortController(); const {signal}=scope;
    const root=document.querySelector('#main-content'); root.dataset.page=page;Night.wallpapers.mount(page);
    if(['home','about','gallery'].includes(page))Night.gallery.mount();
    const $=s=>root.querySelector(s);
    const on=(node,type,handler,options={})=>node?.addEventListener(type,handler,{...options,signal});
    const module=(html,className='')=>{const e=document.createElement('section');e.className='page-console '+className;e.innerHTML=html;return e;};
    const afterHeading=e=>$('.page-heading')?.after(e);
    function pulse(node){if(Night.motion.level()==='full'&&node?.animate){const animation=node.animate([{opacity:.35,transform:'translateY(6px)'},{opacity:1,transform:'none'}],{duration:360,easing:'ease-out'});animations.add(animation);animation.onfinish=()=>animations.delete(animation);}}
    if(page==='home') {
      const board=module(`<div class="console-label"><span>CITY COORDINATES / 城市坐标</span><span>01—04 / SELECT A NODE</span></div><div class="city-navigation"><div class="city-map"><svg viewBox="0 0 600 280" aria-hidden="true"><path d="M-10 240L190 40H580M50 290L330 10M170 290L450 10M-10 120H650M-10 200H650M-10 260H650"/><path class="map-route" d="M100 200H230L310 120H470"/></svg>${[['journal','日志档案','01',17,64],['projects','实验工作台','02',40,37],['about','身份档案','03',65,68],['contact','留言频道','04',78,25]].map(([id,name,n,x,y])=>`<button data-city-node="${id}" style="--node-x:${x}%;--node-y:${y}%" aria-pressed="${id==='journal'}"><i></i><b>${n}</b><span>${name}</span></button>`).join('')}<small>NC / PERSONAL NETWORK<br>选择坐标，锁定下一站。</small></div><div class="city-destination"><p class="eyebrow" id="city-code"></p><h2 id="city-title"></h2><p id="city-description"></p><a class="button primary" id="city-enter" href="#/journal">接入这个坐标 ↗</a></div></div>`,'home-console');
      $('.hero')?.after(board);
      const data={journal:['01 / ARCHIVE','构建日志','检索设计与技术记录，读取每次迭代的想法。'],projects:['02 / WORKBENCH','作品实验室','切换工作台，挑战夜城跑酷或弹奏键盘钢琴。'],about:['03 / IDENTITY','个人档案','翻转身份卡，读取这套设计背后的选择。'],contact:['04 / CHANNEL','留言终端','编辑信号，保存到当前浏览器的本地档案。']};
      function select(id){if(!data[id])return;board.dataset.node=id;$('#city-code').textContent=data[id][0];$('#city-title').textContent=data[id][1];$('#city-description').textContent=data[id][2];$('#city-enter').href='#/'+id;board.querySelectorAll('[data-city-node]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.cityNode===id)));pulse($('.city-destination'));}
      on(board,'click',e=>{const b=e.target.closest('[data-city-node]');if(b)select(b.dataset.cityNode);});select('journal');
    }
    if(page==='journal') {
      const board=module(`<div class="console-label"><span>ARCHIVE READER / 档案读取器</span><span>SELECT → PREVIEW → READ</span></div><div class="archive-reader"><div class="archive-slots" role="group" aria-label="选择日志摘要">${Night.posts.map((p,i)=>`<button data-preview-post="${p.id}" aria-pressed="${i===0}"><span>${String(i+1).padStart(2,'0')}</span>${esc(p.category)}<b>↗</b></button>`).join('')}</div><div class="archive-preview"><p class="eyebrow" id="archive-meta"></p><h2 id="archive-title"></h2><p id="archive-summary"></p><a id="archive-read" href="#/journal" class="text-link">打开完整日志 ↗</a></div><div class="archive-decoration" aria-hidden="true"><span>FILE</span><b id="archive-number">01</b><i></i></div></div>`,'archive-console');afterHeading(board);
      function preview(id){const p=Night.posts.find(p=>p.id===id);if(!p)return;$('#archive-meta').textContent=p.category+' / '+p.date;$('#archive-title').textContent=p.title;$('#archive-summary').textContent=p.summary;$('#archive-read').href='#/post/'+p.id;$('#archive-number').textContent=String(Night.posts.indexOf(p)+1).padStart(2,'0');board.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.previewPost===id)));pulse($('.archive-preview'));}
      on(board,'click',e=>{const b=e.target.closest('[data-preview-post]');if(b)preview(b.dataset.previewPost);});preview(Night.posts[0].id);
      const modes=document.createElement('div');modes.className='archive-modes';modes.setAttribute('role','group');modes.setAttribute('aria-label','日志布局');modes.innerHTML='<button class="small-button" data-layout="grid" aria-pressed="true">▦ 网格</button><button class="small-button" data-layout="list" aria-pressed="false">☷ 列表</button>';$('.result-line').append(modes);
      on(modes,'click',e=>{const b=e.target.closest('[data-layout]');if(!b)return;$('#posts').classList.toggle('archive-list',b.dataset.layout==='list');modes.querySelectorAll('button').forEach(v=>v.setAttribute('aria-pressed',String(v===b)));pulse($('#posts'));});
      on($('.journal-tools'),'click',e=>{if(e.target.closest('[data-filter]'))pulse($('#posts'));});on($('#search'),'input',()=>pulse($('#posts')));
    }
    if(page==='projects') {
      const board=module(`<div class="console-label"><span>EXPERIMENT BAY / 实验工作台</span><span>SELECT A BUILD</span></div><div class="workbench-tabs" role="group" aria-label="选择工作台作品">${Night.projects.map((p,i)=>`<button data-build="${p.id}" aria-pressed="${i===0}"><span>0${i+1}</span>${esc(p.id==='piano'?'零界键盘钢琴':'夜城疾跑')}</button>`).join('')}</div><div class="workbench"><div class="bench-device" id="bench-device" data-build="runner"><div class="bench-grid"></div><div class="bench-model"><div class="bench-screen"><span id="bench-symbol">RUN</span><div class="bench-wave" aria-hidden="true"></div><small id="bench-screen-label">ENDLESS RUNNER</small></div><div class="bench-base"></div><i></i><i></i></div><div class="bench-spec" aria-hidden="true">STRUCTURE / HTML<br>INTERFACE / CSS<br>LOGIC / JAVASCRIPT</div><span class="bench-axis">X + / Y + / Z +</span></div><div class="bench-details"><p class="eyebrow" id="bench-type"></p><h2 id="bench-title"></h2><p id="bench-description"></p><div class="bench-controls"><button class="small-button" id="bench-blueprint" aria-pressed="false">切换蓝图视图</button><button class="button primary" id="bench-run" data-project="runner">打开这个作品 ↗</button></div><p class="subtle">鼠标移动可倾斜模型；键盘和触屏可直接切换与打开。</p></div></div>`,'projects-console');$('.project-grid').replaceWith(board);
      function select(id){const p=Night.projects.find(p=>p.id===id);if(!p)return;$('#bench-device').dataset.build=id;$('#bench-type').textContent=p.type+' / '+p.tech;$('#bench-title').textContent=p.name;$('#bench-description').textContent=p.description;$('#bench-screen-label').textContent=id==='piano'?'KEYBOARD × WEB AUDIO':'ENDLESS RUNNER';$('#bench-symbol').textContent=id==='piano'?'C / E / G':'RUN';$('#bench-run').dataset.project=id;$('#bench-run').textContent=id==='runner'?'开始闯关 ↗':'开始弹琴 ↗';board.querySelectorAll('[data-build]').forEach(b=>{if(b.tagName==='BUTTON')b.setAttribute('aria-pressed',String(b.dataset.build===id));});pulse($('.bench-details'));}
      on(board,'click',e=>{const b=e.target.closest('button[data-build]');if(b)select(b.dataset.build);});
      on($('#bench-blueprint'),'click',e=>{const active=board.classList.toggle('blueprint');e.currentTarget.setAttribute('aria-pressed',String(active));e.currentTarget.textContent=active?'返回实体视图':'切换蓝图视图';});
      const model=$('.bench-model'),device=$('#bench-device');
      on(device,'pointermove',e=>{if(e.pointerType!=='mouse'||Night.motion.level()!=='full')return;const r=device.getBoundingClientRect();model.style.setProperty('--tilt-x',((e.clientY-r.top)/r.height-.5)*-15+'deg');model.style.setProperty('--tilt-y',((e.clientX-r.left)/r.width-.5)*20+'deg');});
      const reset=()=>{model.style.setProperty('--tilt-x','0deg');model.style.setProperty('--tilt-y','0deg');};on(device,'pointerleave',reset);on(window,'night:motion',reset);select('runner');
    }
    if(page==='about') {
      const card=$('.identity-card'),shell=document.createElement('div');shell.className='identity-shell';card.before(shell);shell.append(card);
      const front=document.createElement('div');front.className='identity-front';front.innerHTML=card.innerHTML;
      const back=document.createElement('div');back.className='identity-back';back.setAttribute('aria-hidden','true');back.inert=true;back.innerHTML='<p class="eyebrow">REVERSE SIDE / 档案背面</p><h2>NEON<br><span>NΞON // 零界</span></h2><dl><dt>IDENTITY</dt><dd>个人博客与前端实验</dd><dt>STACK</dt><dd>HTML / CSS / JAVASCRIPT</dd><dt>HOBBIES</dt><dd>游戏 / 读书 / 魔方</dd><dt>ORIGIN</dt><dd>Web 编程技术课程作业</dd></dl><p>保留好奇，持续构建。</p>';
      card.replaceChildren(front,back);const flip=document.createElement('button');flip.className='small-button identity-flip';flip.textContent='翻转身份卡 ↻';flip.setAttribute('aria-pressed','false');shell.append(flip);
      on(flip,'click',()=>{const flipped=card.classList.toggle('flipped');flip.setAttribute('aria-pressed',String(flipped));flip.textContent=flipped?'返回身份卡正面 ↶':'翻转身份卡 ↻';front.setAttribute('aria-hidden',String(flipped));front.inert=flipped;back.setAttribute('aria-hidden',String(!flipped));back.inert=!flipped;});
      const dossier=module(`<div class="console-label"><span>DESIGN DOSSIER / 设计档案</span><span>SELECT A LAYER</span></div><div class="dossier-tabs" role="group" aria-label="档案层级"><button data-dossier="visual" aria-pressed="true">01 / 视觉</button><button data-dossier="structure" aria-pressed="false">02 / 结构</button><button data-dossier="interaction" aria-pressed="false">03 / 交互</button></div><div class="dossier-content"><span id="dossier-index">01</span><div><h2 id="dossier-title"></h2><p id="dossier-description"></p></div></div>`,'dossier-console');($('.favorite-light')||$('.identity-layout')).after(dossier);
      const data={visual:['01','让风格成为自己的表达','黑红企业界面、荧光强调色、原创三刃徽记与城市影像，组成零界的视觉语言。'],structure:['02','让每一页都有自己的职责','首页是坐标导航，日志负责阅读，作品提供实验，关于解释设计，留言保留本地反馈。'],interaction:['03','让操作有可理解的回应','不同页面提供坐标选择、档案预览、工作台、身份卡与信号回执；支持键盘、触屏和减少动效。']};
      function select(id){if(!data[id])return;$('#dossier-index').textContent=data[id][0];$('#dossier-title').textContent=data[id][1];$('#dossier-description').textContent=data[id][2];dossier.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.dossier===id)));pulse($('.dossier-content'));}
      on(dossier,'click',e=>{const b=e.target.closest('[data-dossier]');if(b)select(b.dataset.dossier);});select('visual');
    }
    if(page==='contact') {
      $('.message-side').innerHTML=`<p class="eyebrow">SIGNAL COMPOSER / 信号编辑器</p><h2>把想法，<br>变成一段<span>信号。</span></h2><div class="signal-scope" aria-hidden="true">${Array.from({length:25},(_,i)=>`<i style="--bar:${12+(i*37%70)}%"></i>`).join('')}</div><ol class="signal-checklist"><li id="signal-name">01 / 昵称待输入</li><li id="signal-topic">02 / 主题待选择</li><li id="signal-text">03 / 正文待输入</li></ol><p id="signal-readiness" role="status">等待信号输入。</p><div class="signal-receipt" id="signal-receipt" hidden role="status"></div><div class="channel-spec"><span>DESTINATION</span><strong>THIS BROWSER</strong><span>NETWORK</span><strong>NO UPLOAD</strong></div>`;
      function update(){const name=$('#visitor-name').value.trim(),topic=$('#message-topic').value,text=$('#message-text').value.trim();const values=[name.length>=2&&name.length<=20,!!topic,text.length>=10&&text.length<=500];const labels=['昵称','主题','正文'];['name','topic','text'].forEach((id,i)=>{$('#signal-'+id).classList.toggle('complete',values[i]);$('#signal-'+id).textContent=String(i+1).padStart(2,'0')+' / '+labels[i]+(values[i]?'已就绪':'待完善');});const count=values.filter(Boolean).length;$('.signal-scope').style.setProperty('--signal-strength',String(.2+count*.25));$('#signal-readiness').textContent=count===3?'信号已就绪，可以保存到本地终端。':`信号组装中 / ${count} 项已就绪`;}
      on($('#message-form'),'input',()=>{update();$('#signal-receipt').hidden=true;});on($('#message-form'),'change',update);on($('#clear-draft'),'click',()=>queueMicrotask(()=>{if(!signal.aborted)update();}));
      savedHandler=()=>{update();const receipt=$('#signal-receipt');receipt.hidden=false;receipt.replaceChildren();const title=document.createElement('strong'),text=document.createElement('p');title.textContent='LOCAL SAVE / 已写入本机';text.textContent='记录数 '+Night.messages().length+' / 回执 '+new Date().toLocaleTimeString('zh-CN',{hour12:false});receipt.append(title,text);pulse(receipt);};update();
    }
    if(page==='post'&&$('.article-body')) {
      const bar=module('<div class="reader-progress"><i id="reading-fill"></i></div><span id="reading-percent">阅读进度 0%</span><button class="small-button" id="focus-reading" aria-pressed="false">进入专注阅读</button>','reading-console');$('.article-top').after(bar);
      function progress(){const r=$('.article-body').getBoundingClientRect(),range=Math.max(1,r.height-innerHeight*.65);const value=Math.round(Math.min(1,Math.max(0,(innerHeight*.2-r.top)/range))*100);$('#reading-fill').style.width=value+'%';$('#reading-percent').textContent='阅读进度 '+value+'%';}
      on(window,'scroll',progress,{passive:true});on(window,'resize',progress);on($('#focus-reading'),'click',e=>{const active=root.classList.toggle('focus-reading');e.currentTarget.setAttribute('aria-pressed',String(active));e.currentTarget.textContent=active?'退出专注阅读':'进入专注阅读';progress();});progress();
    }
  }
  return {mount,dispose,messageSaved:()=>savedHandler()};
})();
